def main():
    now=datetime.now(timezone.utc).isoformat();checkpoint=read(ROOT/'verification/resource-readiness-checkpoint.json');ready=read(ROOT/'verification/biwn-resource-readiness-checks.json');mcp=read(ROOT/'verification/resource-readiness-MCP-check.json');assert mcp['status']=='fresh_installed_two_client_readiness_and_unexercised_world_scope_passed'
